// The rules the brief requires, as invariants over the payment spec.
const STATUSES = ['none', 'authorizing', 'authorized', 'declined', 'failed', 'captured', 'voided', 'refunded'];
const decided = (s) => s !== 'none' && s !== 'authorizing';

export const stateInvariants = [
  { name: 'known-status', pred: (s) => STATUSES.includes(s.status) },
  { name: 'authorized-is-1-or-2', pred: (s) => s.status === 'none' || s.authorized === 1 || s.authorized === 2 },
  { name: 'capture-within-authorized', pred: (s) => s.captured <= s.authorized },
  { name: 'refund-within-captured', pred: (s) => s.refunded <= s.captured },
  { name: 'at-most-3-requests', pred: (s) => s.requests <= 3 },
  { name: 'pending-within-requests', pred: (s) => s.pending >= 0 && s.pending <= s.requests },
  { name: 'voided-captured-nothing', pred: (s) => s.status !== 'voided' || (s.captured === 0 && s.refunded === 0) },
  { name: 'money-only-after-authorization', pred: (s) => s.captured === 0 || s.status === 'captured' || s.status === 'refunded' },
  { name: 'refunded-means-all', pred: (s) => s.status !== 'refunded' || (s.captured > 0 && s.refunded === s.captured) },
  { name: 'captured-not-fully-refunded', pred: (s) => s.status !== 'captured' || (s.captured > 0 && s.refunded < s.captured) },
  { name: 'failed-after-3', pred: (s) => s.status !== 'failed' || s.requests === 3 },
];

export const transitionInvariants = [
  { name: 'first-answer-decides', pred: (pre, a, d, post) => !(a === 'COMPLETE' && decided(pre.status)) || post.status === pre.status },
  { name: 'authorized-never-changes', pred: (pre, a, d, post) => pre.status === 'none' || post.authorized === pre.authorized },
  { name: 'money-monotone', pred: (pre, a, d, post) => post.captured >= pre.captured && post.refunded >= pre.refunded && post.requests >= pre.requests },
  { name: 'only-authorized-captures', pred: (pre, a, d, post) => post.captured === pre.captured || pre.status === 'authorized' },
  { name: 'only-authorizing-retries', pred: (pre, a, d, post) => post.requests === pre.requests || pre.status === 'authorizing' || pre.status === 'none' },
];

