// Capture real traces from src/host.impl.ts: seeded random walks over one
// payment id, one NDJSON window per step, written to spec/traces/.
// Usage: node spec/capture.mjs [walks=60] [steps=14]
import { mkdirSync, writeFileSync, rmSync } from 'node:fs';
import createHost from '../src/host.impl.ts';

const ID = 'p';
const walks = Number(process.argv[2] || 60);
const steps = Number(process.argv[3] || 14);
const dir = new URL('./traces/', import.meta.url);
rmSync(dir, { recursive: true, force: true });
mkdirSync(dir, { recursive: true });

let seed = 7;
const rand = (n) => { seed = (seed * 1103515245 + 12345) % 2147483648; return seed % n; };
const pick = (xs) => xs[rand(xs.length)];

const observe = async (h) => {
  const p = await h.payment(ID);
  const pending = (await h.pendingEffects()).filter((e) => e.from === ID).length;
  if (!p) return { status: 'none', authorized: 0, captured: 0, refunded: 0, requests: 0, pending };
  return { ...p, pending };
};

for (let w = 0; w < walks; w++) {
  const h = await createHost();
  const lines = [];
  for (let s = 0; s < steps; s++) {
    const pre = await observe(h);
    const action = pick(['AUTHORIZE', 'TIMED_OUT', 'TIMED_OUT', 'CAPTURE', 'VOID', 'REFUND', 'REFUND', 'COMPLETE', 'COMPLETE']);
    let data = {};
    if (action === 'AUTHORIZE') { data = { amount: pick([0, 1, 2, 2, 1, 3]) }; await h.authorize(ID, data.amount); }
    if (action === 'TIMED_OUT') await h.timedOut(ID);
    if (action === 'CAPTURE') { data = { amount: pick([0, 1, 2, 3]) }; await h.capture(ID, data.amount); }
    if (action === 'VOID') await h.void(ID);
    if (action === 'REFUND') { data = { amount: pick([0, 1, 2, 3]) }; await h.refund(ID, data.amount); }
    if (action === 'COMPLETE') {
      data = { outcome: pick(['ok', 'ok', 'failed']) };
      const mine = (await h.pendingEffects()).filter((e) => e.from === ID);
      if (mine.length) await h.completeEffect(pick(mine).id, data.outcome);
    }
    lines.push(JSON.stringify({ pre, action, data, post: await observe(h) }));
  }
  writeFileSync(new URL(`walk-${String(w).padStart(3, '0')}.ndjson`, dir), lines.join('\n') + '\n');
}
console.log(`wrote ${walks} traces`);

