import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

const approve = async (h, payment, outcome = 'ok') => {
  const e = (await h.pendingEffects()).find((x) => x.from === payment);
  await h.completeEffect(e.id, outcome);
};

test('fresh system', async () => {
  const h = await createHost();
  assert.deepEqual(await h.pendingEffects(), []);
  assert.equal(await h.payment('p'), null);
});

test('authorize sends one request', async () => {
  const h = await createHost();
  assert.deepEqual(await h.authorize('p', 2), { ok: true });
  const effs = await h.pendingEffects();
  assert.equal(effs.length, 1);
  assert.equal(effs[0].kind, 'card.authorize');
  assert.equal(effs[0].from, 'p');
  assert.deepEqual(effs[0].data, { amount: 2 });
  assert.deepEqual(await h.payment('p'), { status: 'authorizing', authorized: 2, captured: 0, refunded: 0, requests: 1 });
  assert.equal((await h.authorize('p', 1)).ok, false);
  assert.equal((await h.authorize('q', 3)).ok, false);
  assert.equal((await h.authorize('q', 0)).ok, false);
  assert.equal(await h.payment('q'), null);
});

test('unknown payments refused', async () => {
  const h = await createHost();
  for (const r of [await h.timedOut('x'), await h.capture('x', 1), await h.void('x'), await h.refund('x', 1)]) assert.equal(r.ok, false);
});

test('timeouts retry up to 3 then fail; late answers ignored', async () => {
  const h = await createHost();
  await h.authorize('p', 1);
  assert.equal((await h.timedOut('p')).ok, true);
  assert.equal((await h.timedOut('p')).ok, true);
  assert.equal((await h.pendingEffects()).length, 3);
  assert.equal((await h.payment('p')).requests, 3);
  assert.equal((await h.timedOut('p')).ok, true);
  assert.equal((await h.payment('p')).status, 'failed');
  assert.equal((await h.payment('p')).requests, 3);
  assert.equal((await h.timedOut('p')).ok, false);
  await approve(h, 'p');
  assert.equal((await h.payment('p')).status, 'failed');
  assert.equal((await h.pendingEffects()).length, 2);
});

test('first answer decides', async () => {
  const h = await createHost();
  await h.authorize('p', 2);
  await h.timedOut('p');
  await approve(h, 'p', 'failed');
  assert.equal((await h.payment('p')).status, 'declined');
  await approve(h, 'p', 'ok');
  assert.equal((await h.payment('p')).status, 'declined');
  assert.equal((await h.pendingEffects()).length, 0);
  assert.equal((await h.capture('p', 1)).ok, false);
});

test('capture, refund', async () => {
  const h = await createHost();
  await h.authorize('p', 1);
  await approve(h, 'p');
  assert.equal((await h.timedOut('p')).ok, false);
  assert.equal((await h.capture('p', 2)).ok, false);
  assert.equal((await h.refund('p', 1)).ok, false);
  assert.equal((await h.capture('p', 1)).ok, true);
  assert.equal((await h.capture('p', 1)).ok, false);
  assert.equal((await h.void('p')).ok, false);
  assert.equal((await h.refund('p', 2)).ok, false);
  assert.equal((await h.refund('p', 1)).ok, true);
