'use strict';
// SAM v2 strict-profile spec of the stateful core of src/host.impl.ts, for ONE
// payment id. Payments are independent, so one id covers the behaviour.
// status 'none' = no payment with this id; pending = this payment's
// outstanding card.authorize effects (any one may be completed next).

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const MAX_REQUESTS = 3;
const INITIAL_STATE = { status: 'none', authorized: 0, captured: 0, refunded: 0, requests: 0, pending: 0 };
const MAX_AUTHORIZED = 3;
const isUnit = (a) => a === 1 || a === 2;
const isCaptureAmount = (a) => a === 1 || a === 2 || a === 3;
const AMOUNTS = [0, 1, 2, 3, 4];

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      status: { type: 'string' },
      authorized: { type: 'number' },
      captured: { type: 'number' },
      refunded: { type: 'number' },
      requests: { type: 'number' },
      pending: { type: 'number' },
    },
    actions: {
      AUTHORIZE: { action: (data = {}) => ({ ...data }), schema: { amount: 'number' }, domain: AMOUNTS.map((amount) => ({ amount })) },
      TIMED_OUT: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      CAPTURE: { action: (data = {}) => ({ ...data }), schema: { amount: 'number' }, domain: AMOUNTS.map((amount) => ({ amount })) },
      VOID: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      INCREASE: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      EXPIRE: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      REFUND: { action: (data = {}) => ({ ...data }), schema: { amount: 'number' }, domain: AMOUNTS.map((amount) => ({ amount })) },
      COMPLETE: { action: (data = {}) => ({ ...data }), schema: { outcome: 'string' }, domain: [{ outcome: 'ok' }, { outcome: 'failed' }] },
    },
    acceptors: {
      AUTHORIZE: (model) => (proposal, { reject, next, unchanged }) => {
        if (!isUnit(proposal.amount)) return reject('bad-amount');
        if (model.status !== 'none') return reject('payment-exists');
        next.status = 'authorizing';
        next.authorized = proposal.amount;
        next.requests = 1;
        next.pending = model.pending + 1;
        unchanged('captured', 'refunded');
      },
      TIMED_OUT: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status !== 'authorizing') return reject('not-authorizing');
        if (model.requests >= MAX_REQUESTS) {
          next.status = 'failed';
          unchanged('authorized', 'captured', 'refunded', 'requests', 'pending');
          return;
        }
        next.requests = model.requests + 1;
        next.pending = model.pending + 1;
        unchanged('status', 'authorized', 'captured', 'refunded');
      },
      CAPTURE: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status === 'none') return reject('unknown-payment');
        if (!isCaptureAmount(proposal.amount)) return reject('bad-amount');
        if (model.status !== 'authorized') return reject('not-authorized');
        if (proposal.amount > model.authorized) return reject('exceeds-authorized');
        next.captured = proposal.amount;
        next.status = 'captured';
        unchanged('authorized', 'refunded', 'requests', 'pending');
      },
      VOID: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status !== 'authorized') return reject('not-authorized');
        next.status = 'voided';
        unchanged('authorized', 'captured', 'refunded', 'requests', 'pending');
      },
      INCREASE: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status !== 'authorized') return reject('not-authorized');
        if (model.authorized >= MAX_AUTHORIZED) return reject('authorized-at-max');
        next.authorized = model.authorized + 1;
        unchanged('status', 'captured', 'refunded', 'requests', 'pending');
      },
      EXPIRE: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status !== 'authorized') return reject('not-authorized');
        next.status = 'expired';
        unchanged('authorized', 'captured', 'refunded', 'requests', 'pending');
      },
      REFUND: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.status === 'none') return reject('unknown-payment');
        if (!isUnit(proposal.amount)) return reject('bad-amount');
        if (model.status !== 'captured') return reject('not-captured');
        const refunded = model.refunded + proposal.amount;
        if (refunded > model.captured) return reject('exceeds-captured');
        next.refunded = refunded;
        if (refunded === model.captured) next.status = 'refunded';
        else unchanged('status');
        unchanged('authorized', 'captured', 'requests', 'pending');
      },
      COMPLETE: (model) => (proposal, { reject, next, unchanged }) => {
        if (model.pending === 0) return reject('no-pending-effect');
        next.pending = model.pending - 1;
        if (model.status === 'authorizing') next.status = proposal.outcome === 'ok' ? 'authorized' : 'declined';
        else unchanged('status');
        unchanged('authorized', 'captured', 'refunded', 'requests');
      },
    },
    reactors: [],
  },
});

